export function phonopyDerivationModel(value){
 if(!record(value)||value.schema!=='symmetry-lab-phonopy-derivation-1'||typeof value.fingerprint!=='string'||!Array.isArray(value.points)||value.points.length!==2||!['A','B'].every(id=>value.points.some(p=>p.id===id&&record(p.input)&&record(p.result)))||!Array.isArray(value.tasks)||!value.tasks.length)return {status:'invalid'};
 if(!value.tasks.every(t=>typeof t.id==='string'&&shapeOK(t)&&Number.isInteger(t.stage)&&t.stage>=1&&t.stage<=5&&typeof t.available==='boolean'&&(!t.available||matrixOK(t.expected?.re,t.shape)&&matrixOK(t.expected?.im,t.shape))))return {status:'invalid'};
 return {status:'available',result:value};
}

