 const snapshot=()=>clone(state);
 function sync(){if(!current())return;const busy=!!job||!!readJob;for(const id of ['load','derive','grade','diagnose','reference-export','copy'])if($(id))$(id).disabled=busy||(id==='derive'&&!(state.input&&state.confirmed&&state.approximation));if($('cancel'))$('cancel').disabled=!busy;if($('status'))$('status').textContent=notice;}
 function predictionsHTML(){return '<section class="pd-section"><h4>'+esc(T.prediction)+'</h4><p>'+esc(T.predictionHelp)+'</p>'+predictions.map(p=>'<label for="pd-predict-'+p.id+'">'+esc(p.question)+'</label><select id="pd-predict-'+p.id+'"><option value="">—</option>'+p.options.map((label,i)=>'<option value="'+i+'"'+(state.predictions[p.id]===String(i)?' selected':'')+'>'+esc(label)+'</option>').join('')+'</select>'+button('predict-check-'+p.id,T.predictCheck)+'<p id="pd-predict-feedback-'+p.id+'" role="status">'+(state.predictionChecked[p.id]?esc(p.feedback):'')+'</p>').join('')+'</section>';}
